-- Name: set_trip_location_geom(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_trip_location_geom() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                NEW.geom :=
                    ST_SetSRID(
                        ST_MakePoint(NEW.longitude, NEW.latitude),
                        4326
                    );
                RETURN NEW;
            END;
            $$;


